result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/clause_extract.py", "content": """"Parse a plain-text contract into structured JSON.

Structure:
    {
      "sections": [
        {"number": 1, "heading": "DEFINITIONS",
         "subsections": [{"number": "1.1", "text": "..."}]},
        ...
      ],
      "defined_terms": {"Confidential Information": "1.1", ...},
      "gaps": [3]
    }
"""

import json
import re

SECTION_RE = re.compile(r"^SECTION\s+(\d+)\.\s*(.*?)\s*$")
SUBSECTION_RE = re.compile(r"^(\d+\.\d+)\s+(.*)$")
DEFINED_TERM_RE = re.compile(r'^"([^"]+)"\s+means\b')


def parse_contract(text):
    sections = []
    defined_terms = {}

    current = None
    current_sub = None

    def flush_sub():
        nonlocal current_sub
        if current and current_sub is not None:
            number, lines = current_sub
            text_value = " ".join(line.strip() for line in lines).strip()
            current["subsections"].append({"number": number, "text": text_value})
            m = DEFINED_TERM_RE.match(text_value)
            if m:
                defined_terms[m.group(1)] = number
        current_sub = None

    for line in text.splitlines():
        line = line.rstrip()
        if not line.strip():
            continue

        sec = SECTION_RE.match(line)
        if sec:
            flush_sub()
            heading = sec.group(2)
            if heading.endswith("."):
                heading = heading[:-1]
            current = {
                "number": int(sec.group(1)),
                "heading": heading,
                "subsections": [],
            }
            sections.append(current)
            continue

        sub = SUBSECTION_RE.match(line.strip())
        if sub:
            flush_sub()
            current_sub = (sub.group(1), [sub.group(2)])
            continue

        # Continuation of the previous subsection.
        if current_sub is not None:
            current_sub[1].append(line.strip())
        elif current is not None:
            current["heading"] += " " + line.strip()

    flush_sub()

    numbers = [s["number"] for s in sections]
    gaps = []
    if numbers:
        for n in range(min(numbers), max(numbers) + 1):
            if n not in numbers:
                gaps.append(n)

    return {
        "sections": sections,
        "defined_terms": dict(sorted(defined_terms.items())),
        "gaps": gaps,
    }


def parse_file(path):
    with open(path, encoding="utf-8") as f:
        return parse_contract(f.read())


def main():
    import sys

    path = sys.argv[1] if len(sys.argv) > 1 else "fixtures/sample_contract.txt"
    print(json.dumps(parse_file(path), indent=2))


if __name__ == "__main__":
    main()
