                    "number": "1.1",
                    "text": '"Confidential Information" means any non-public information.',
                },
                {
                    "number": "1.2",
                    "text": '"Term" means the period defined in Section 4.',
                },
            ],
        },
        {
            "number": 2,
            "heading": "LICENSE GRANT",
            "subsections": [
                {
                    "number": "2.1",
                    "text": "Licensor grants Licensee a non-exclusive license.",
                }
            ],
        },
        {
            "number": 4,
            "heading": "TERM AND TERMINATION",
            "subsections": [
                {"number": "4.1", "text": "The Term begins on the Effective Date."}
            ],
        },
    ],
    "defined_terms": {
        "Confidential Information": "1.1",
        "Term": "1.2",
    },
    "gaps": [3],
}


def test_fixture_parses_to_exact_expected_json():
    assert parse_file(FIXTURE) == EXPECTED


def test_output_is_valid_json():
    assert json.loads(json.dumps(parse_file(FIXTURE))) == EXPECTED


def test_heading_without_trailing_period():
    text = textwrap.dedent(
        """\
        SECTION 5. GOVERNING LAW
        5.1 This Agreement is governed by the laws of Delaware.
        """
    )
    result = parse_contract(text)
    assert result["sections"] == [
        {
            "number": 5,
            "heading": "GOVERNING LAW",
            "subsections": [
                {"number": "5.1", "text": "This Agreement is governed by the laws of Delaware."}
            ],
        }
    ]


def test_subsection_spanning_two_lines():
    text = textwrap.dedent(
        """\
        SECTION 6. MISCELLANEOUS.
        6.1 This Agreement constitutes the entire agreement
        between the parties hereto.
        """
    )
    result = parse_contract(text)
    assert result["sections"][0]["subsections"] == [
        {
            "number": "6.1",
            "text": (
                "This Agreement constitutes the entire agreement "
                "between the parties hereto."
            ),
        }
    ]
